-- Arbeitsrecht Berufsbildung > Pflichten von Auszubildenden > Sorgfalt bei der Arbeit (§ 13 BBiG)
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Muss ein Fachinformatiker bei der Programmierung sorgfältig arbeiten?', 2, '[{"text": "Ja", "correct": true, "because": "§ 13 BBiG fordert Sorgfalt bei der Arbeit"}, {"text": "Nein", "correct": false, "because": "Sorgfalt ist eine gesetzliche Pflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Fachinformatiker unsauberen Code schreiben, wenn er schnell fertig werden will?', 2, '[{"text": "Nein", "correct": true, "because": "§ 13 BBiG verlangt sorgfältige Ausführung"}, {"text": "Ja", "correct": false, "because": "Sorgfalt hat Vorrang vor Schnelligkeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist ein Fachinformatiker verpflichtet, Fehler in seiner Arbeit selbst zu korrigieren?', 2, '[{"text": "Ja", "correct": true, "because": "§ 13 BBiG umfasst Sorgfalt bei der Fehlerbehebung"}, {"text": "Nein", "correct": false, "because": "Fehlerkorrektur ist Teil der Sorgfalt"}]'),
('00000000-0000-0000-0000-000000000000', 'Darf ein Fachinformatiker Hardware achtlos behandeln, wenn sie alt ist?', 2, '[{"text": "Nein", "correct": true, "because": "§ 13 BBiG fordert Sorgfalt unabhängig vom Zustand"}, {"text": "Ja", "correct": false, "because": "Sorgfalt gilt für alle Arbeitsmittel"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss ein Fachinformatiker Sicherheitsvorkehrungen beim Netzwerkaufbau beachten?', 2, '[{"text": "Ja", "correct": true, "because": "§ 13 BBiG verlangt sorgfältiges Arbeiten"}, {"text": "Nein", "correct": false, "because": "Sicherheit ist Teil der Sorgfalt"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche gesetzliche Grundlage verpflichtet einen Fachinformatiker zur Sorgfalt bei der Arbeit?', 2, '[{"text": "§ 13 BBiG", "correct": true, "because": "Regelt die Pflichten des Auszubildenden"}, {"text": "§ 14 BBiG", "correct": false, "because": "Bezieht sich auf Pflichten des Betriebs"}, {"text": "§ 17 BBiG", "correct": false, "because": "Regelt die Vergütung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was sollte ein Fachinformatiker tun, wenn er einen Fehler in seinem Code bemerkt?', 3, '[{"text": "Den Fehler sorgfältig beheben", "correct": true, "because": "§ 13 BBiG fordert Sorgfalt"}, {"text": "Den Fehler ignorieren", "correct": false, "because": "Widerspricht der Sorgfaltspflicht"}, {"text": "Den Ausbilder die Arbeit übernehmen lassen", "correct": false, "because": "Eigene Sorgfalt ist gefordert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Tätigkeit zeigt Sorgfalt bei der Arbeit eines Fachinformatikers?', 3, '[{"text": "Dokumentation des Codes", "correct": true, "because": "Entspricht § 13 BBiG und guter Praxis"}, {"text": "Schnelles Abschließen ohne Tests", "correct": false, "because": "Fehlende Tests sind unsorgfältig"}, {"text": "Hardware unsachgemäß lagern", "correct": false, "because": "Widerspricht der Sorgfalt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wer überwacht die Sorgfalt eines Fachinformatikers bei der Arbeit?', 2, '[{"text": "Der Ausbilder", "correct": true, "because": "§ 14 BBiG verpflichtet ihn zur Kontrolle"}, {"text": "Die Berufsschule", "correct": false, "because": "Schule hat keine direkte Aufsicht"}, {"text": "Die IHK", "correct": false, "because": "IHK prüft nur die Ausbildung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert, wenn ein Fachinformatiker nicht sorgfältig arbeitet?', 3, '[{"text": "Er kann verwarnt oder gekündigt werden", "correct": true, "because": "Verstoß gegen § 13 BBiG hat Konsequenzen"}, {"text": "Der Betrieb übernimmt die Verantwortung", "correct": false, "because": "Nicht vorgesehen"}, {"text": "Die IHK entschädigt den Betrieb", "correct": false, "because": "IHK ist nicht zuständig"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Handlungen zeigen Sorgfalt bei der Arbeit eines Fachinformatikers?', 4, '[{"text": "Regelmäßige Tests des Codes", "correct": true, "because": "Sorgfalt gemäß § 13 BBiG"}, {"text": "Sichere Handhabung von Hardware", "correct": true, "because": "Teil der Sorgfaltspflicht"}, {"text": "Schnelles Arbeiten ohne Dokumentation", "correct": false, "because": "Dokumentation fehlt"}, {"text": "Überprüfung von Netzwerksicherheit", "correct": true, "because": "Sorgfalt bei der Arbeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Konsequenzen drohen einem Fachinformatiker bei mangelnder Sorgfalt?', 3, '[{"text": "Verwarnung durch den Betrieb", "correct": true, "because": "Reaktion auf Pflichtverletzung"}, {"text": "Kündigung bei schwerem Verstoß", "correct": true, "because": "§ 22 BBiG erlaubt dies"}, {"text": "Automatische Beförderung", "correct": false, "because": "Nicht logisch"}, {"text": "Verlust der Vergütung", "correct": false, "because": "Nicht direkt vorgesehen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Sorgfalt bei der Arbeit eines Fachinformatikers?', 4, '[{"text": "Sauberer und lesbarer Code", "correct": true, "because": "Entspricht § 13 BBiG"}, {"text": "Sorgfältige Installation von Hardware", "correct": true, "because": "Teil der Pflicht"}, {"text": "Ignorieren von Sicherheitslücken", "correct": false, "because": "Widerspricht Sorgfalt"}, {"text": "Einhaltung von Deadlines mit Qualität", "correct": true, "because": "Sorgfalt und Effizienz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Unterstützung kann ein Fachinformatiker erwarten, um sorgfältig zu arbeiten?', 3, '[{"text": "Unterweisung durch den Ausbilder", "correct": true, "because": "§ 14 Abs. 1 BBiG unterstützt Sorgfalt"}, {"text": "Bereitstellung geeigneter Arbeitsmittel", "correct": true, "because": "§ 14 Abs. 1 BBiG hilft dabei"}, {"text": "Freistellung von Aufgaben", "correct": false, "because": "Nicht vorgesehen"}, {"text": "Zusätzliche Pausen", "correct": false, "because": "Nicht direkt relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Handlungen verstoßen gegen die Sorgfaltspflicht eines Fachinformatikers?', 3, '[{"text": "Ungetesteten Code abgeben", "correct": true, "because": "Widerspricht § 13 BBiG"}, {"text": "Hardware unsachgemäß anschließen", "correct": true, "because": "Fehlende Sorgfalt"}, {"text": "Netzwerkkonfiguration prüfen", "correct": false, "because": "Entspricht der Pflicht"}, {"text": "Fehler protokollieren", "correct": false, "because": "Zeigt Sorgfalt"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Sorgfalt bedeutet, Aufgaben gewissenhaft zu erledigen. b) Ein Fachinformatiker darf Fehler ignorieren.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Sorgfalt ist Pflicht, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) widerspricht § 13 BBiG"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Fachinformatiker muss Hardware schonend behandeln. b) Sorgfalt gilt nur für wichtige Projekte.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Sorgfalt gilt immer, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Sorgfalt umfasst das Testen von Software. b) Ein Fachinformatiker kann unsorgfältig arbeiten, wenn niemand es merkt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Testen ist Sorgfalt, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) widerspricht § 13 BBiG"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Ein Fachinformatiker muss Netzwerksicherheit sorgfältig prüfen. b) Sorgfalt ist nur in der Probezeit erforderlich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Sorgfalt gilt immer, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Sorgfalt bedeutet auch, Fehler zu melden. b) Der Betrieb übernimmt die Sorgfalt für den Fachinformatiker.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Fehler melden ist Sorgfalt, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

